def is_oven_ready(temperature):
    is_ready = False
    if temperature >= 150 and temperature <= 250:
        is_ready = True
    else:
        is_ready = False
    return is_ready

def calculate_bus_ticket_price(age):
    ticket_price = 3.0
    if age < 12 or age > 65:
        return ticket_price
    else:
        ticket_price = ticket_price + 2
        return ticket_price

def calculate_product_discount(price, online_order):
    discount = 0.0
    if online_order == True:
        if price > 100.0:
            discount = 5.0
    else:
        discount = 5.0
    return discount

def calculate_charging_time_minutes(initial_battery_level):
    minutes_passed = 0
    full_charge_level = 100
    battery_level = initial_battery_level

    while True:
        if battery_level >= full_charge_level:
            break
        elif battery_level <= 80:
            battery_level = battery_level + 2
            minutes_passed = minutes_passed + 1
        elif battery_level > 80:
            battery_level = battery_level + 1
            minutes_passed = minutes_passed + 1

    return minutes_passed

def largest_number(numbers):
    largest = numbers[0]
    i = 0
    is_negative = False

    while i < len(numbers) and is_negative == False:
        if numbers[i] < 0:
            is_negative = True
        if numbers[i] >= 0 and numbers[i] > largest:
            largest = numbers[i]
            continue
        i += 1

    return largest

def is_eligible_for_bonus(homework_grades, exemption):
    bonus_points = 0

    for i in range(len(homework_grades)):
        if exemption == False:
            if homework_grades[i] >= 80:
                bonus_points += 1
        else:
            bonus_points += 1

    if bonus_points < 5:
        return False
    else:
        return True

def calculate_daily_salary(week_day, day_shift, worked_hours):
    base_hour_salary = 15.0

    if week_day and day_shift:
        return base_hour_salary * worked_hours
    else:
        base_hour_salary = base_hour_salary + (base_hour_salary / 2)
        return base_hour_salary * worked_hours
